/**
 * The one shared implementation of frozen-script byte/interpreter capture.
 * Both prepare.ts's script arm (prepareTaskV3Execution) and
 * prepare-script-target.ts's typed prepareScriptTarget() call
 * captureScriptTarget() below, so the two never drift into two copies of the
 * same capture logic.
 */
import { createHash } from "node:crypto";
import path from "node:path";
import { UsageError } from "../../core/errors.js";
import { isBunStandaloneMain } from "../resolve-akm-bin.js";
const SCRIPT_INTERPRETERS = Object.freeze({
    ".sh": "sh",
    ".ts": "bun",
    ".js": "bun",
    ".ps1": "powershell",
    ".cmd": "cmd",
    ".bat": "cmd",
    ".py": "python",
    ".rb": "ruby",
    ".go": "go",
    ".pl": "perl",
    ".php": "php",
    ".lua": "lua",
    ".r": "rscript",
    ".swift": "swift",
    ".kt": "kotlin",
    ".kts": "kotlin",
});
const SHEBANG_INTERPRETERS = [
    [/^(bash|sh|zsh|dash|ksh)$/, "sh"],
    [/^python[0-9.]*$/, "python"],
    [/^ruby$/, "ruby"],
    [/^perl$/, "perl"],
    [/^php$/, "php"],
    [/^lua$/, "lua"],
    [/^node$/, "node"],
];
function interpreterFromShebang(bytes) {
    if (!bytes || bytes.length < 2 || bytes[0] !== 0x23 || bytes[1] !== 0x21)
        return undefined;
    const newline = bytes.indexOf(0x0a);
    const lineBytes = newline === -1 ? bytes.subarray(2) : bytes.subarray(2, newline);
    const tokens = Buffer.from(lineBytes).toString("utf8").trim().split(/\s+/).filter(Boolean);
    const [first, second] = tokens;
    const named = first?.split("/").pop() === "env" ? second : first?.split("/").pop();
    if (!named)
        return undefined;
    for (const [pattern, interpreter] of SHEBANG_INTERPRETERS) {
        if (pattern.test(named))
            return interpreter;
    }
    return undefined;
}
function nodeStripsTypeScript() {
    const features = process.features;
    return Boolean(features?.typescript);
}
export function scriptInterpreter(extension, ref, bytes) {
    const interpreter = SCRIPT_INTERPRETERS[extension] ?? (extension === "" ? interpreterFromShebang(bytes) : undefined);
    if (!interpreter) {
        throw new UsageError(`Task v3 script target ${JSON.stringify(ref)} has no closed runtime interpreter for extension ${JSON.stringify(extension)}.`, "TASK_TARGET_UNSUPPORTED");
    }
    if (interpreter !== "bun")
        return interpreter;
    if (process.versions.bun) {
        return isBunStandaloneMain() ? "bun-standalone" : "bun";
    }
    if (extension === ".js" || (extension === ".ts" && nodeStripsTypeScript())) {
        return "node";
    }
    throw new UsageError(`Task v3 script target ${JSON.stringify(ref)} requires Bun for ${extension} execution, but this runtime cannot provide it.`, "TASK_TARGET_UNSUPPORTED");
}
/**
 * Read a script's bytes off disk (or the caller's own read seam, following a
 * symlink to wherever it points) and freeze the interpreter/digest shape every
 * script dispatch needs. `ref` is used only for interpreter-selection error
 * messages — it is the script's own qualified ref, never a synthetic task ref.
 * `bundleRoot` is the script's working directory.
 */
export function captureScriptTarget(ref, file, bundleRoot, readFile) {
    const extension = path.extname(file).toLowerCase();
    const raw = readFile(file, bundleRoot);
    const bytes = Uint8Array.from(raw);
    return Object.freeze({
        interpreter: scriptInterpreter(extension, ref, bytes),
        extension,
        bytesBase64: Buffer.from(bytes).toString("base64"),
        byteLength: bytes.byteLength,
        sha256: createHash("sha256").update(bytes).digest("hex"),
        cwd: path.resolve(bundleRoot),
    });
}
